import re
f='index.html'; s=open(f).read()
def rep(pat,new,count=1):
    global s
    s,n=re.subn(pat,lambda m:new,s,count=count,flags=re.S)
    assert n>=1,pat
rep(r'<title>.*?</title>','<title>BSG Athena++-equivalent (his deck values)</title>')
rep(r'<h1>.*?</h1>',"<h1>BSG Athena++-equivalent arm (prod_lhxo): Linhao Ma's deck values with Athena++'s Doppler velocity at CFL 0.3, vs earlier arms and Ma, Bildsten &amp; Jiang (2026)</h1>")
rep(r'<p class="banner" id="s-arm">.*?</p>','''<p class="banner" id="s-arm"><b>What this arm is.</b> The AthenaK deck of the Linhao-exact setup with the values of his <code>athinput.bsg_star.rusty</code> and the kick-fixed Doppler velocity, and <b>no sink or error-limit leak mimic</b>. (1) GM = 19.78 M<sub>&#9737;</sub>, his floors and his seed threshold (6.15&times;10<sup>&minus;7</sup> g cm<sup>&minus;3</sup>), one noise deviate per merged group. (2) His SMR angular grid, radiation included: 128<sup>2</sup> at 20&ndash;35 and 55&ndash;80 R<sub>&#9737;</sub>, 256<sup>2</sup> at 35&ndash;55 R<sub>&#9737;</sub> (merge_lat, rigid momentum). (3) No first-order flux correction, as in his deck. (4) <code>&lt;rad_m1&gt;/doppler_vel = vstar_nbe</code> with <code>he_bc_linhao_fis = iter</code>: the radiation Doppler terms use Athena++'s predicted v*, without the start-up kick of the earlier vstar_n arms. Twin off, ray rotation off. <b>Not matched:</b> the time step. His cfl_rad 0.025 multiplies dt (dt ~4.8 s); this arm uses CFL 0.3 with the radiation-modified signal speed (dt ~100&ndash;170 s). We no longer attempt an exact reproduction of his run. Fresh start from t = 0 on 11-06 (14:50 PST); tlim 57.4 d, the paper's end time.</p>''')
rep(r'(?<=<p class="lede"><b>Interim page\.</b>).*?</p>'," Our AthenaK run of the 20 M<sub>&#9737;</sub> blue supergiant of\n      <a href=\"https://arxiv.org/abs/2609.28656\">arXiv:2609.28656</a> set up from <b>Linhao Ma's own Athena++ code (bsg_star.cpp) and deck values, except the radiative transfer and the time step</b>: branch vstarfix-1106 (3b1d3dc19, unmerged), binary athena_gpu_he_star_m1_v3_fmadoff (md5 20efaed0), deck bsgLI_lhx_exact_o.athinput, 4 H200 on hpc-sm-01-05. Matched to his code: his profile and &plusmn;2.5 % isobaric noise, his\n      inner ghosts (profile &rho;, P; ghost-1 v<sub>r</sub> for zero HLLC mass flux), his half-range ghost intensities at the\n      inner face, his outer boundary (outflow &rho; &prop; r<sup>&minus;2</sup>), his radial grid (192 base cells + one\n      SMR level on 35&ndash;55 R<sub>&#9737;</sub> = 256 faces), his 120-angle set as fixed rays. One deliberate fix: the\n      isothermal atmosphere above 52.5 R<sub>&#9737;</sub> is hydrostatic in GM/r<sup>2</sup> (his code uses g &prop; r<sup>+2</sup>).\n      Plotted the same way as the paper's Figures 2, 3, 4 and 6, with the published figure beside each one.</p>")
rep(r'Ours \(Athena\+\+-equivalent: Linhao-exact \+ vstar_n \+ merged base, athpp-doface-1105, Caltech\)',"Ours (Athena++-equivalent: his deck values + vstar_nbe, vstarfix-1106, Caltech)")
def row(lab,ours):
    # replace the last <td> of the row whose th is lab
    global s
    p=r'(<tr><th scope="row">'+lab+r'</th><td>.*?</td><td>).*?(</td></tr>)'
    s,n=re.subn(p,lambda m:m.group(1)+ours+m.group(2),s,count=1,flags=re.S); assert n==1,lab
row('Sponge, floor',"no sponge; his floors: &rho; 6.15&times;10<sup>&minus;14</sup> g cm<sup>&minus;3</sup>, T 108 K, P 8.9&times;10<sup>&minus;3</sup> (cgs)")
row('Grid',"256 &times; 256 &times; 256 stored; <b>his radial faces exactly</b>: 0.3125 R<sub>&#9737;</sub> on 20&ndash;35 and 55&ndash;80, 0.15625 on 35&ndash;55 R<sub>&#9737;</sub> (the paper's &ldquo;196&rdquo; base cells must be 192: 2560 blocks of 16<sup>3</sup>); <b>his angular SMR by merging</b>: lateral cells merged x2 at 20&ndash;35 and 55&ndash;80 R<sub>&#9737;</sub> = 128<sup>2</sup>, 256<sup>2</sup> at 35&ndash;55 R<sub>&#9737;</sub>, for hydro and radiation (merge_lat rigid)")
row('Total cells',"16,777,216 stored (16 MeshBlocks of 256 &times; 64 &times; 64); fewer independent cells in the merged shells")
row('Hydro',"HLLC [5], PLM, RK2; <b>no first-order flux correction</b>, as his deck; <b>no well-balanced scheme</b>; CFL 0.3 with the radiation-modified signal speed (dt ~100&ndash;170 s; his cfl_rad 0.025 multiplies dt, giving dt ~4.8 s)")
row('Gravity',"point mass as an Athena++-style source term, <b>his deck GM = 2.625&times;10<sup>27</sup> cm<sup>3</sup> s<sup>&minus;2</sup> (19.78 M<sub>&#9737;</sub>)</b>, not the paper's 20 M<sub>&#9737;</sub>")
row('Radiation',"implicit grey two-moment (E, F) with a variable Eddington tensor from global-direction short characteristics; <b>fixed level-symmetric LQ10 set, 120 directions</b> (his Athena++ angle set; no rotation, to match him; orientation global, his is local); hesdirk2, conservative2 exchange; <b>Doppler terms with Athena++'s predicted v* (doppler_vel = vstar_nbe, wall flux F<sub>is</sub> = Picard iterate)</b>; no error_limit leak mimic")
row('Seed',"<b>&plusmn;2.5 % isobaric noise</b> (his &rho; &times; [1 + 0.05 (U &minus; 0.5)] where &rho; &gt; 6.15&times;10<sup>&minus;7</sup> g cm<sup>&minus;3</sup>, his threshold, P and E unchanged), one deviate per merged group as his coarse cells; zero velocity")
row('Star',"L = 5.581&times;10<sup>38</sup> erg s<sup>&minus;1</sup> (from Ma's profile); GM 19.78 M<sub>&#9737;</sub> (his deck); r<sub>photo,IC</sub> of his profile in the Fig. 3 notes (MESA's is ~50&ndash;51)")
row('Run length',"57.4 d (tlim), from t = 0; current time in the status line above")
rep(r'<p class="tnote"><b>Matched / fixed / cannot match</b>.*?</p>','''<p class="tnote"><b>Matched / fixed / not matched</b> (table in the deck &lt;comment&gt;, partly from earlier arms): matched to bsg_star.cpp and athinput.bsg_star.rusty: IC, noise and its threshold, inner and outer boundaries, opacity tables and clamp, radial grid, angular SMR by merging, 120-angle set, GM, floors, no FOFC; fixed by the user: the atmosphere gravity; kept as our numerical defaults (user): split_c2p_once, am_transport, dt_retry; not matched: the radiation method (M1+VET instead of discrete ordinates), his convergence tolerance 10<sup>&minus;6</sup> (ours is tighter), VL2 (we use RK2), the time step (CFL 0.3 by user choice, not his cfl_rad).</p>''')
rep(r'<p class="tnote"><b>What is the same and what is not:</b>.*?</p>','''<p class="tnote"><b>What is the same and what is not:</b> domain, opacity tables, the outer outflow rule, HLLC, the point-mass gravity without a well-balanced scheme and the absence of a sponge follow his setup. Differences: the two-moment VET transport instead of 120 transported intensities, the time step (about 20&ndash;35 times his), the stretched radial grid and merged lateral cells instead of block SMR, and the 1-D profile top (his profile ends at 52.5 R<sub>&#9737;</sub>, with his isothermal extension above; the paper quotes MESA's photosphere, about 50&ndash;51 R<sub>&#9737;</sub>). The paper writes r<sub>max</sub> = &ldquo;80 M<sub>&#9737;</sub>&rdquo; (a typo for R<sub>&#9737;</sub>).</p>''')
rep(r'<h2><span class="tag">3 arms</span>.*?</h2>','<h2><span class="tag">Arms</span>This arm (prod_lhxo) against the earlier arms and the Linhao-exact production</h2>')
rep(r'<figcaption>Solid red: this arm.*?(?=Top row, from the 0\.5-d dumps)','<figcaption>Solid red: this arm (doface_1105/prod_lhxo). Dash-dot green: vstar_n + base merge, CFL 0.3 (prod_vsnmlat_ns, stopped 23.7 d). Dotted orange: vstar_n only (prod_doface, stopped ~18 d). Dashed blue: the Linhao-exact production (bsgli_1104/prod, finished at 57.4 d). Solid purple: kick fix, GM 20 (prod_vstarfix, stopped 15.4 d). Dotted brown: kicked, GM 20 (prod_vsnmlat_thr1e7, stopped 35 d). The comparison runs are drawn to at least 18.5 d, or 2 d past this arm. Their decks differ, see each label, so a split is not caused by one key alone. ')
rep(r'alt="Six panels against time for both runs:','alt="Six panels against time for all arms:')
rep(r'Kinetic energy of this arm \(vstar_n \+ merged base\)','Kinetic energy of this arm (prod_lhxo)')
rep(r"<span>Our run: AthenaK on 4 H200.*?(?=Interim page, regenerated)","<span>Our run: AthenaK on 4 H200 on hpc-sm-01-05 (alloc 5719508, 4 MeshBlocks per GPU), branch vstarfix-1106 (3b1d3dc19, unmerged), binary athena_gpu_he_star_m1_v3_fmadoff (md5 20efaed0), deck doface_1105/prep3d/bsgLI_lhx_exact_o.athinput; launcher prep3d/run_lhxo_3d.sh. Comparison runs: see the arms section. ")
open(f,'w').write(s)
g=open('gen_status.py').read()
m=re.search(r"^RUN = \(.*?$",g,flags=re.M); print(m.group(0)[:900]); print(g[m.end():m.end()+500])
